#!/usr/bin/env bash
# Build (if needed) and run the MPC2500 emulator in a live window.
#   Needs: gcc, make, libsdl2-dev, python3 + Pillow (front-panel artwork is generated by tools/make_skin.py)
# Firmware: put your file in ./firmware/ (see firmware/README.txt) or pass --firmware FILE. Other options: emu/mpc2500emu --help
# CompactFlash: card/card.img is inserted if present (or pass CARD=image / --card image). RAM: --ram MB (default: the stock 16 MB; 128 = the EXM128 expansion).
# Controls: click a panel cell to hold it; click the pad grid; mouse wheel, drag on the jog wheel or [ ] = DATA wheel;
#           keys in panel_map.txt; TAB (hold) = fast-forward; Ctrl+R = power cycle; Esc = quit.
set -euo pipefail
cd "$(dirname "$0")"
if [ ! -f skin/skin.bmp ] || [ tools/make_skin.py -nt skin/skin.bmp ]; then python3 -I tools/make_skin.py skin; fi
make -s -C emu all
if [ ! -f card/card.img ] && [ -d archive/kit/2500Kit ]; then
  python3 -I tools/mkfat16.py card/card.img 128 archive/kit/2500Kit/KIT.PGM archive/kit/2500Kit/BOOMA*.SND
fi
exec emu/mpc2500emu "$@"
